
:root {
    --bg: #f5f8fe;
    --surface: rgba(255,255,255,.9);
    --surface-strong: #ffffff;
    --line: #dfe7f2;
    --line-soft: rgba(24, 47, 92, .08);
    --text: #0d1b35;
    --muted: #64748b;
    --muted-2: #90a0b7;
    --blue: #2f80ed;
    --blue-deep: #175edb;
    --cyan: #48c3ff;
    --violet: #6c63ff;
    --teal: #14b8a6;
    --green: #22c55e;
    --pink: #ec4899;
    --orange: #f59e0b;
    --red: #ef4444;
    --ink-shadow: 0 30px 80px rgba(15, 29, 61, .12);
    --soft-shadow: 0 16px 34px rgba(15, 29, 61, .07);
    --card-shadow: 0 10px 24px rgba(15, 29, 61, .05);
    --radius-xl: 34px;
    --radius-lg: 26px;
    --radius-md: 20px;
    --radius-sm: 16px;
}

* {
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    margin: 0;
    min-height: 100vh;
    color: var(--text);
    font-family: "Manrope", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    background: radial-gradient(circle at 8% 0%, rgba(72,195,255,.14), transparent 22rem), radial-gradient(circle at 100% 10%, rgba(108,99,255,.12), transparent 20rem), radial-gradient(circle at 50% 100%, rgba(47,128,237,.08), transparent 22rem), linear-gradient(180deg, #f9fbff 0%, #f3f7fd 100%);
    overflow-x: hidden;
}

a, button, input {
    font: inherit;
}

a {
    color: inherit;
    text-decoration: none;
}

button {
    border: 0;
    background: none;
}

.icon-sprite {
    position: absolute;
    width: 0;
    height: 0;
    overflow: hidden;
}

.inline-icon {
    display: block;
    fill: none;
    stroke: currentColor;
    stroke-width: 2;
    stroke-linecap: round;
    stroke-linejoin: round;
}

.page {
    width: min(100%, 680px);
    margin: 0 auto;
    padding: max(20px, env(safe-area-inset-top)) 16px max(28px, env(safe-area-inset-bottom));
}

.card {
    position: relative;
    overflow: hidden;
    border-radius: var(--radius-xl);
    background: var(--surface);
    border: 1px solid rgba(255,255,255,.95);
    box-shadow: var(--ink-shadow);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
}

    .card::before {
        content: "";
        position: absolute;
        inset: 0 0 auto;
        height: 6px;
        background: linear-gradient(90deg, var(--cyan), var(--blue), var(--violet));
        z-index: 5;
    }

.hero {
    position: relative;
}

.cover-art {
    position: relative;
    /*min-height: 248px;*/
    overflow: hidden;
    padding: 28px 24px 106px;
    background: linear-gradient(180deg, rgba(255,255,255,.18), rgba(255,255,255,.28)), url("data:image/png;base64,");
    background-size: cover;
    background-position: center center;
    background-repeat: no-repeat;
    border-bottom: 1px solid rgba(24, 47, 92, .05);
}

    .cover-art::before,
    .cover-art::after {
        content: "";
        position: absolute;
        border-radius: 999px;
        pointer-events: none;
    }

    .cover-art::before {
        width: 210px;
        /*height: 210px;*/
        right: -56px;
        top: -54px;
        background: radial-gradient(circle, rgba(47,128,237,.16), rgba(47,128,237,0) 70%);
    }

    .cover-art::after {
        width: 180px;
        height: 180px;
        left: -50px;
        bottom: -40px;
        background: radial-gradient(circle, rgba(72,195,255,.12), rgba(72,195,255,0) 72%);
    }

.mesh {
    position: absolute;
    inset: 0;
    opacity: .18;
    pointer-events: none;
    background-image: linear-gradient(rgba(47,128,237,.06) 1px, transparent 1px), linear-gradient(90deg, rgba(47,128,237,.06) 1px, transparent 1px);
    background-size: 18px 18px;
    mask-image: linear-gradient(180deg, rgba(0,0,0,.35), transparent 70%);
    -webkit-mask-image: linear-gradient(180deg, rgba(0,0,0,.35), transparent 70%);
}

.cover-head {
    position: relative;
    z-index: 1;
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 14px;
}

.cover-chip {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 10px 14px;
    border-radius: 999px;
    background: rgba(255,255,255,.85);
    border: 1px solid rgba(255,255,255,.95);
    color: var(--blue-deep);
    font-size: .76rem;
    font-weight: 800;
    letter-spacing: .1em;
    text-transform: uppercase;
    box-shadow: 0 10px 20px rgba(15,29,61,.05);
}

.cover-mark {
    display: grid;
    place-items: center;
    width: 56px;
    height: 56px;
    flex: 0 0 auto;
    border-radius: 18px;
    color: white;
    background: linear-gradient(135deg, var(--blue), var(--violet));
    box-shadow: 0 14px 28px rgba(47,128,237,.22);
    font-family: "Cormorant Garamond", Georgia, serif;
    font-size: 1rem;
    font-weight: 700;
    letter-spacing: .06em;
}

.cover-copy {
    position: relative;
    z-index: 1;
    margin-top: 26px;
    max-width: 420px;
}

.cover-title {
    margin: 0;
    font-size: clamp(2rem, 7vw, 2.9rem);
    line-height: .96;
    letter-spacing: -.05em;
    font-weight: 900;
}

    .cover-title .accent {
        color: var(--blue);
    }

.cover-sub {
    margin-top: 10px;
    color: var(--text);
    font-size: 1rem;
    font-weight: 700;
}

.cover-meta {
    margin-top: 10px;
    color: var(--muted);
    font-size: .92rem;
    line-height: 1.65;
    max-width: 36ch;
}

.cover-stats {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    margin-top: 18px;
}

.stat-pill {
    padding: 10px 14px;
    border-radius: 999px;
    background: rgba(255,255,255,.82);
    border: 1px solid var(--line-soft);
    color: var(--text);
    font-size: .8rem;
    font-weight: 700;
    box-shadow: 0 8px 16px rgba(15,29,61,.04);
}

.identity-row {
    position: absolute;
    left: 20px;
    right: 20px;
    bottom: -50px;
    z-index: 3;
    display: flex;
    align-items: flex-end;
    gap: 14px;
}

.portrait-shell {
    width: 122px;
    height: 122px;
    flex: 0 0 auto;
    padding: 5px;
    border-radius: 30px;
    background: linear-gradient(145deg, var(--cyan), var(--blue), var(--violet));
    box-shadow: 0 18px 36px rgba(47,128,237,.24);
}

    .portrait-shell img {
        width: 100%;
        height: 100%;
        display: block;
        border-radius: 26px;
        object-fit: cover;
        object-position: center 18%;
        border: 3px solid rgba(255,255,255,.97);
        background: #e6edf8;
    }

.identity-card {
    flex: 1;
    min-width: 0;
    padding: 16px 18px 17px;
    border-radius: 24px;
    background: rgba(255,255,255,.9);
    border: 1px solid rgba(255,255,255,.95);
    box-shadow: var(--soft-shadow);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
}

.identity-label {
    color: var(--muted);
    font-size: .76rem;
    font-weight: 800;
    letter-spacing: .12em;
    text-transform: uppercase;
}

.identity-name {
    margin-top: 8px;
    font-size: 1.6rem;
    line-height: 1;
    font-weight: 900;
    letter-spacing: -.04em;
}

    .identity-name .accent {
        color: var(--blue);
    }

.identity-role {
    margin-top: 8px;
    color: var(--text);
    font-size: .94rem;
    font-weight: 700;
}

.identity-desc {
    margin-top: 6px;
    color: var(--muted);
    font-size: .84rem;
    line-height: 1.5;
}

.content {
    padding: 74px 20px 22px;
}

.action-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
    margin-bottom: 24px;
}

.button {
    min-height: 56px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    padding: 14px 16px;
    border-radius: 18px;
    cursor: pointer;
    font-size: .95rem;
    font-weight: 800;
    transition: transform .22s ease, box-shadow .22s ease, border-color .22s ease;
}

    .button:hover {
        transform: translateY(-2px);
    }

    .button:active {
        transform: translateY(0) scale(.985);
    }

.button-primary {
    color: white;
    background: linear-gradient(135deg, var(--blue-deep), var(--violet));
    box-shadow: 0 16px 34px rgba(47,128,237,.28);
}

.button-secondary {
    color: var(--text);
    background: rgba(255,255,255,.95);
    border: 1px solid var(--line);
    box-shadow: var(--card-shadow);
}

.section + .section {
    margin-top: 26px;
}

.section-head {
    display: flex;
    align-items: center;
    gap: 12px;
    margin: 0 2px 14px;
}

    .section-head h2 {
        margin: 0;
        white-space: nowrap;
        color: var(--muted);
        font-size: .77rem;
        font-weight: 900;
        letter-spacing: .14em;
        text-transform: uppercase;
    }

.section-line {
    flex: 1;
    height: 1px;
    background: linear-gradient(90deg, var(--line), transparent);
}

.intro-card {
    padding: 18px 18px 16px;
    border-radius: 22px;
    background: linear-gradient(180deg, rgba(255,255,255,.96), rgba(248,251,255,.9));
    border: 1px solid var(--line-soft);
    box-shadow: var(--card-shadow);
}

.intro-text {
    color: var(--muted);
    font-size: .92rem;
    line-height: 1.72;
}

.link-list {
    display: grid;
    gap: 11px;
}

.link-card {
    display: grid;
    grid-template-columns: 48px minmax(0,1fr) auto;
    align-items: start;
    gap: 13px;
    min-height: 88px;
    padding: 16px 14px;
    border-radius: 20px;
    background: rgba(255,255,255,.94);
    border: 1px solid var(--line-soft);
    box-shadow: var(--card-shadow);
    transition: transform .22s ease, box-shadow .22s ease, border-color .22s ease;
}

    .link-card:hover {
        transform: translateY(-2px);
        box-shadow: 0 16px 28px rgba(15,29,61,.08);
        border-color: rgba(47,128,237,.15);
    }

.icon-tile {
    width: 48px;
    height: 48px;
    display: grid;
    place-items: center;
    border-radius: 16px;
    color: var(--accent);
    background: color-mix(in srgb, var(--accent) 11%, white);
}

.link-main {
    min-width: 0;
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 6px;
    padding-top: 2px;
    padding-bottom: 2px;
}

.link-title {
    display: block;
    font-size: 1rem;
    font-weight: 800;
    line-height: 1.25;
    white-space: normal;
    overflow: visible;
    text-overflow: clip;
}

.link-subtitle {
    display: block;
    margin-top: 0;
    color: var(--muted);
    font-size: .84rem;
    line-height: 1.45;
    white-space: normal;
    overflow: visible;
    text-overflow: clip;
}

.arrow {
    align-self: center;
    color: var(--muted-2);
}

.compact-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 11px;
}

.compact-link {
    min-height: 112px;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    padding: 16px;
    border-radius: 20px;
    background: rgba(255,255,255,.94);
    border: 1px solid var(--line-soft);
    box-shadow: var(--card-shadow);
    transition: transform .22s ease, box-shadow .22s ease;
}

    .compact-link:hover {
        transform: translateY(-2px);
        box-shadow: 0 16px 28px rgba(15,29,61,.08);
    }

    .compact-link .icon-tile {
        width: 42px;
        height: 42px;
        border-radius: 14px;
    }

.compact-title {
    font-size: .89rem;
    font-weight: 800;
    line-height: 1.3;
}

.compact-sub {
    margin-top: 7px;
    color: var(--muted);
    font-size: .8rem;
    line-height: 1.5;
}

.footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin-top: 26px;
    padding: 18px 2px 2px;
    border-top: 1px solid var(--line);
    color: var(--muted);
    font-size: .8rem;
}

    .footer strong {
        color: var(--text);
    }

.modal {
    position: fixed;
    inset: 0;
    z-index: 40;
    display: grid;
    place-items: center;
    padding: 16px;
    background: rgba(9,18,38,.48);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transition: opacity .22s ease, visibility .22s ease;
}

    .modal.is-open {
        opacity: 1;
        visibility: visible;
        pointer-events: auto;
    }

.modal-panel {
    width: min(100%, 480px);
    padding: 24px;
    border-radius: 26px;
    background: rgba(255,255,255,.97);
    border: 1px solid rgba(255,255,255,.95);
    box-shadow: 0 26px 70px rgba(9,18,38,.22);
    transform: translateY(12px) scale(.98);
    transition: transform .22s ease;
}

.modal.is-open .modal-panel {
    transform: translateY(0) scale(1);
}

.modal-head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 14px;
}

.modal-title {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 900;
}

.modal-copy {
    margin: 8px 0 18px;
    color: var(--muted);
    font-size: .9rem;
    line-height: 1.6;
}

.modal-close {
    width: 38px;
    height: 38px;
    display: grid;
    place-items: center;
    border-radius: 12px;
    background: #f1f5fb;
    color: var(--muted);
    cursor: pointer;
}

.field-label {
    display: block;
    margin: 0 0 8px;
    color: var(--muted);
    font-size: .82rem;
    font-weight: 800;
}

.input {
    width: 100%;
    min-height: 54px;
    padding: 13px 15px;
    border-radius: 16px;
    border: 1px solid var(--line);
    background: #fff;
    color: var(--text);
    outline: none;
    transition: border-color .2s ease, box-shadow .2s ease;
}

    .input:focus {
        border-color: rgba(47,128,237,.42);
        box-shadow: 0 0 0 4px rgba(47,128,237,.12);
    }

.modal-actions {
    display: grid;
    grid-template-columns: 1fr 1.25fr;
    gap: 12px;
    margin-top: 18px;
}

.toast {
    position: fixed;
    left: 50%;
    bottom: max(20px, env(safe-area-inset-bottom));
    z-index: 50;
    transform: translate(-50%, 28px);
    opacity: 0;
    pointer-events: none;
    display: inline-flex;
    align-items: center;
    gap: 10px;
    max-width: calc(100vw - 30px);
    padding: 14px 16px;
    border-radius: 16px;
    background: #0f1c38;
    color: white;
    box-shadow: 0 16px 40px rgba(15,28,56,.32);
    transition: transform .22s ease, opacity .22s ease;
    font-weight: 700;
}

    .toast.show {
        transform: translate(-50%, 0);
        opacity: 1;
    }

    .toast .inline-icon {
        color: #69eacb;
    }

@media (max-width: 768px) {
    .cover-art {
        /*min-height: 228px;*/
        padding: 22px 18px 84px;
    }

    .identity-row {
        position: relative;
        left: auto;
        right: auto;
        bottom: auto;
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 14px;
        margin: -56px 16px 0;
    }

    .portrait-shell {
        width: 118px;
        height: 118px;
        margin: 0 auto;
    }

        .portrait-shell img {
            object-position: center 8%;
        }

    .identity-card {
        width: 100%;
        text-align: center;
        padding: 16px 16px 18px;
    }

    .identity-name {
        font-size: 1.46rem;
        line-height: 1.05;
    }

    .content {
        padding: 20px 16px 20px;
    }

    .action-row, .compact-grid, .modal-actions {
        grid-template-columns: 1fr;
    }

    .footer {
        flex-direction: column;
        align-items: flex-start;
    }
}

@media (max-width: 430px) {
    .cover-art {
        /*min-height: 214px;*/
        padding-bottom: 80px;
    }

    .identity-row {
        margin: -52px 14px 0;
    }

    .portrait-shell {
        width: 112px;
        height: 112px;
    }

    .identity-card {
        padding: 15px 14px 17px;
    }

    .content {
        padding-top: 18px;
    }

    .link-card {
        grid-template-columns: 48px minmax(0,1fr);
    }

    .arrow {
        display: none;
    }
}

@media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
        transition-duration: .01ms !important;
        animation-duration: .01ms !important;
        scroll-behavior: auto !important;
    }
}


/* Colorful professional refresh */
body {
    background: radial-gradient(circle at 8% 0%, rgba(72,195,255,.20), transparent 22rem), radial-gradient(circle at 100% 8%, rgba(108,99,255,.18), transparent 22rem), radial-gradient(circle at 86% 62%, rgba(47,128,237,.10), transparent 20rem), radial-gradient(circle at 12% 90%, rgba(20,184,166,.10), transparent 18rem), linear-gradient(180deg, #fbfdff 0%, #f2f7ff 50%, #eef4fd 100%);
}

.card {
    background: linear-gradient(180deg, rgba(255,255,255,.95), rgba(249,252,255,.92));
    border: 1px solid rgba(255,255,255,.98);
    box-shadow: 0 32px 90px rgba(15, 29, 61, .14);
}

.cover-art {
    background: radial-gradient(circle at 16% 20%, rgba(255,255,255,.88), rgba(255,255,255,0) 28%), radial-gradient(circle at 88% 16%, rgba(72,195,255,.34), rgba(72,195,255,0) 24%), radial-gradient(circle at 78% 82%, rgba(108,99,255,.22), rgba(108,99,255,0) 30%), radial-gradient(circle at 12% 82%, rgba(20,184,166,.12), rgba(20,184,166,0) 24%), linear-gradient(135deg, #ffffff 0%, #f3f8ff 44%, #ebf3ff 100%);
}

.cover-chip {
    background: linear-gradient(180deg, rgba(255,255,255,.96), rgba(244,249,255,.9));
    border-color: rgba(47,128,237,.12);
    color: #154aa8;
    box-shadow: 0 12px 24px rgba(15,29,61,.08);
}

.cover-mark {
    background: linear-gradient(135deg, #155edb 0%, #2f80ed 46%, #6c63ff 100%);
    box-shadow: 0 16px 32px rgba(47,128,237,.26);
}

.cover-title {
    color: #10203f;
}

    .cover-title .accent {
        background: linear-gradient(135deg, #1f74ec, #6b5cff);
        -webkit-background-clip: text;
        background-clip: text;
        color: transparent;
    }

.cover-sub {
    color: #203b69;
}

.cover-meta,
.identity-desc,
.intro-text,
.link-subtitle,
.compact-sub {
    color: #617493;
}

.stat-pill {
    background: linear-gradient(180deg, rgba(255,255,255,.96), rgba(244,248,255,.9));
    border-color: rgba(47,128,237,.12);
    box-shadow: 0 10px 18px rgba(15,29,61,.05);
}

.identity-card {
    background: linear-gradient(180deg, rgba(255,255,255,.98), rgba(245,249,255,.93));
    border: 1px solid rgba(47,128,237,.10);
    box-shadow: 0 18px 36px rgba(15,29,61,.10);
}

.identity-label,
.section-head h2 {
    color: #2a4d86;
}

.identity-role,
.link-title,
.compact-title {
    color: #102544;
}

.button-primary {
    background: linear-gradient(135deg, #175edb 0%, #2f80ed 48%, #6c63ff 100%);
    box-shadow: 0 18px 36px rgba(47,128,237,.30);
}

.button-secondary {
    background: linear-gradient(180deg, #ffffff, #f4f8ff);
    border-color: rgba(47,128,237,.16);
    color: #19365f;
    box-shadow: 0 12px 24px rgba(15,29,61,.08);
}

.section-line {
    background: linear-gradient(90deg, rgba(47,128,237,.35), rgba(108,99,255,.20), transparent);
}

.intro-card {
    position: relative;
    overflow: hidden;
    background: linear-gradient(180deg, rgba(255,255,255,.99), rgba(241,247,255,.96));
    border-color: rgba(47,128,237,.12);
    box-shadow: 0 14px 28px rgba(15,29,61,.06);
}

    .intro-card::before {
        content: "";
        position: absolute;
        left: 0;
        top: 0;
        bottom: 0;
        width: 5px;
        border-radius: 0 999px 999px 0;
        background: linear-gradient(180deg, #48c3ff, #2f80ed, #6c63ff);
    }

.tag {
    background: linear-gradient(180deg, rgba(47,128,237,.12), rgba(72,195,255,.08));
    border-color: rgba(47,128,237,.14);
    color: #1b3662;
    box-shadow: 0 6px 14px rgba(15,29,61,.04);
}

.link-card {
    position: relative;
    overflow: hidden;
    background: linear-gradient(180deg, rgba(255,255,255,.98), rgba(246,250,255,.94));
    border-color: rgba(47,128,237,.10);
    box-shadow: 0 12px 24px rgba(15,29,61,.06);
}

    .link-card::before {
        content: "";
        position: absolute;
        left: 0;
        top: 14px;
        bottom: 14px;
        width: 4px;
        border-radius: 0 999px 999px 0;
        background: linear-gradient(180deg, var(--accent), color-mix(in srgb, var(--accent) 65%, white));
        opacity: .95;
    }

    .link-card:hover {
        box-shadow: 0 18px 34px rgba(15,29,61,.09);
        border-color: rgba(47,128,237,.16);
    }

.icon-tile {
    box-shadow: inset 0 1px 0 rgba(255,255,255,.92), 0 10px 20px rgba(15,29,61,.05);
}

.compact-link {
    position: relative;
    overflow: hidden;
    background: linear-gradient(180deg, rgba(255,255,255,.98), rgba(246,250,255,.94));
    border-color: rgba(47,128,237,.10);
    box-shadow: 0 12px 24px rgba(15,29,61,.06);
}

    .compact-link::before {
        content: "";
        position: absolute;
        left: 16px;
        right: 16px;
        top: 0;
        height: 4px;
        border-radius: 0 0 999px 999px;
        background: linear-gradient(90deg, #48c3ff, #2f80ed, #6c63ff);
        opacity: .95;
    }

    .compact-link:hover {
        box-shadow: 0 18px 34px rgba(15,29,61,.09);
    }

.footer {
    border-top-color: rgba(47,128,237,.14);
    color: #6d7c94;
}



